use vstd::prelude::*;
use std::collections::HashSet;

verus! {

/// Pure spec: remove duplicates from a sequence, keeping first occurrences (stable).
spec fn nub(s: Seq<i32>) -> Seq<i32>
    decreases s.len(),
{
    if s.len() == 0 {
        Seq::<i32>::empty()
    } else {
        let x = s[0];
        let rest = s.drop(1);
        let t = nub(rest);
        if t.contains(x) {
            t
        } else {
            Seq::<i32>::empty().push(x) + t
        }
    }
}

/// The result contains no duplicates.
spec fn no_dups(s: Seq<i32>) -> bool {
    forall|i: int, j: int|
        0 <= i && i < s.len() && 0 <= j && j < s.len() && i != j ==> s[i] != s[j]
}

fn remove_duplicates(nums: Vec<i32>) -> (res: Vec<i32>)
    ensures
        // Exactly the stable de-duplication of the input
        res@ == nub(nums@),
        // In particular, it has no duplicates
        no_dups(res@),
        // And every output element came from the input
        forall|x: i32| res@.contains(x) ==> nums@.contains(x),
{
    let mut seen: HashSet<i32> = HashSet::new();
    let mut res: Vec<i32> = Vec::new();

    for x in nums {
        if seen.insert(x) {
            res.push(x);
        }
    }

    res
}

} // verus!

